### C#

using Google.Cloud.Spanner.Data; using System; using System.Threading; using System.Threading.Tasks; public class ReadLockModeAsyncSample { public async Task ReadLockModeAsync(string projectId, string instanceId, string databaseId) { // Create client with ReadLockMode.Optimistic. string connectionString = $"Data Source=projects/{projectId}/instances/{instanceId}/databases/{databaseId};ReadLockMode=Optimistic"; using var connection = new SpannerConnection(connectionString); await connection.OpenAsync(); // Create transaction options with ReadLockMode.Pessimistic. var transactionOptions = SpannerTransactionCreationOptions.ReadWrite .WithReadLockMode(ReadLockMode.Pessimistic); using var transaction = await connection.BeginTransactionAsync(transactionOptions, null, CancellationToken.None); var cmd = connection.CreateSelectCommand("SELECT AlbumTitle FROM Albums WHERE SingerId = 2 AND AlbumId = 1"); cmd.Transaction = transaction; using (var reader = await cmd.ExecuteReaderAsync()) { while (await reader.ReadAsync()) { Console.WriteLine($"AlbumTitle: {reader.GetFieldValue<string>("AlbumTitle")}"); } } var updateCmd = connection.CreateDmlCommand("UPDATE Albums SET AlbumTitle = 'A New Title' WHERE SingerId = 2 AND AlbumId = 1"); updateCmd.Transaction = transaction; var rowCount = await updateCmd.ExecuteNonQueryAsync(); Console.WriteLine($"{rowCount} records updated."); await transaction.CommitAsync(); } }

### C++

void ReadLockModeSetting(std::string const& project_id, std::string const& instance_id, std::string const& database_id) { namespace spanner = ::google::cloud::spanner; using ::google::cloud::Options; using ::google::cloud::StatusOr; auto db = spanner::Database(project_id, instance_id, database_id); // The read lock mode specified at the client-level will be applied // to all RW transactions. auto options = Options{}.set<spanner::TransactionReadLockModeOption>( spanner::Transaction::ReadLockMode::kOptimistic); auto client = spanner::Client(spanner::MakeConnection(db, options)); auto commit = client.Commit( [&client]( spanner::Transaction const& txn) -> StatusOr<spanner::Mutations> { // Read an AlbumTitle. auto sql = spanner::SqlStatement( "SELECT AlbumTitle from Albums WHERE SingerId = @SingerId and " "AlbumId = @AlbumId", {{"SingerId", spanner::Value(2)}, {"AlbumId", spanner::Value(1)}}); auto rows = client.ExecuteQuery(txn, std::move(sql)); for (auto const& row : spanner::StreamOf<std::tuple<std::string>>(rows)) { if (!row) return row.status(); std::cout << "Current Album Title: " << std::get<0>(*row) << "\n"; } // Update the title. auto update_sql = spanner::SqlStatement( "UPDATE Albums " "SET AlbumTitle = @AlbumTitle " "WHERE SingerId = @SingerId and AlbumId = @AlbumId", {{"AlbumTitle", spanner::Value("A New Title")}, {"SingerId", spanner::Value(2)}, {"AlbumId", spanner::Value(1)}}); auto result = client.ExecuteDml(txn, std::move(update_sql)); if (!result) return result.status(); std::cout << result->RowsModified() << " record(s) updated.\n"; return spanner::Mutations{}; }, // The read lock mode specified at the transaction-level takes // precedence over the read lock mode configured at the client-level. // kPessimistic is used here to demonstrate overriding the client-level // setting. Options{}.set<spanner::TransactionReadLockModeOption>( spanner::Transaction::ReadLockMode::kPessimistic)); if (!commit) throw std::move(commit).status(); std::cout << "Update was successful [spanner_read_lock_mode]\n"; }
